<template><UApp><div v-if="!authReady" class="auth-restoring" role="status"><UIcon name="i-lucide-loader-circle" /><span>Carregando sua conta…</span></div><div v-else-if="!entered" class="login-shell"><button class="btn login-theme" @click="theme=!theme" :aria-label="theme?'Ativar modo escuro':'Ativar modo claro'"><UIcon :name="theme?'i-lucide-moon':'i-lucide-sun'" /><span class="theme-label">{{theme?'Modo escuro':'Modo claro'}}</span></button><div class="finance-backdrop" aria-hidden="true"><svg viewBox="0 0 1200 800" preserveAspectRatio="xMidYMid slice"><defs><pattern id="finance-grid" width="80" height="80" patternUnits="userSpaceOnUse"><path d="M80 0H0V80" fill="none" stroke="currentColor" stroke-width=".5"/></pattern></defs><rect width="1200" height="800" fill="url(#finance-grid)"/><path d="M-20 670L100 620 200 650 330 470 450 510 550 350 680 400 800 250 920 280 1050 130 1220 170" fill="none" stroke="currentColor" stroke-width="3"/><path d="M-20 720L150 650 280 690 420 590 550 610 720 470 880 500 1010 340 1220 370" fill="none" stroke="currentColor" stroke-width="2" opacity=".4"/></svg></div><section class="login-card"><div class="login-mark"><UIcon name="i-lucide-wallet-cards" /></div><div class="caption">SANT FINANÇAS</div><h1>Suas finanças. No seu controle.</h1><p>Contas, parcelas e saldo. Tudo em um só lugar.</p><div v-if="rememberedProfile" class="remembered-profile"><img v-if="rememberedProfile.photoURL && !avatarFailed" :src="rememberedProfile.photoURL" alt="Foto do perfil salvo" referrerpolicy="no-referrer" @error="avatarFailed=true"><span v-else class="avatar-fallback">{{rememberedProfile.name.slice(0,1)}}</span><b>{{rememberedProfile.name}}</b><small>{{rememberedProfile.email}}</small></div><label class="remember-choice"><input type="checkbox" v-model="rememberBrowser">Manter conectado neste navegador</label><button class="btn primary login-action" @click="signIn(false)" :disabled="authBusy">{{authBusy ? 'Conectando...' : rememberedProfile ? 'Continuar como '+rememberedProfile.name.split(' ')[0] : 'Entrar com Google'}}</button><button v-if="rememberedProfile" class="other-account" @click="signIn(true)" :disabled="authBusy">Entrar com outra conta</button><p v-if="message" class="feedback" role="status">{{message}}</p><p class="login-note">Entre com Google para sincronizar seus dados com segurança.</p></section></div><div v-else class="layout"><aside class="sidebar"><a class="brand" href="#monthly" @click.prevent="go('monthly')"><span><UIcon name="i-lucide-wallet-cards" /></span><div>Sant Finanças<small>Seu dinheiro, em equilíbrio</small></div></a><div class="nav"><div class="caption">Seu espaço</div><button v-for="n in nav.filter(item=>item.id!=='settings')" :class="{active:page===n.id}" @click="go(n.id)"><UIcon :name="`i-lucide-${n.icon}`" />{{n.label}}</button></div></aside><main><header class="top"><a class="header-brand" href="#monthly" @click.prevent="go('monthly')"><UIcon name="i-lucide-wallet-cards" /><span>Sant Finanças</span></a><b class="top-title">{{nav.find(n=>n.id===page)?.label}}</b><div class="top-right"><button class="btn" @click="theme=!theme" aria-label="Alternar tema"><UIcon :name="theme ? `i-lucide-sun` : `i-lucide-moon`" /></button><details class="profile-menu"><summary aria-label="Abrir menu da conta"><img v-if="user?.photoURL && !avatarFailed" :src="user.photoURL" alt="Seu perfil" referrerpolicy="no-referrer" @error="avatarFailed=true"><span v-else class="avatar-fallback">{{(state.profileName || user?.displayName || 'U').slice(0,1).toUpperCase()}}</span></summary><div class="profile-popover"><div class="user-identity"><img v-if="user?.photoURL && !avatarFailed" :src="user.photoURL" alt="Foto do seu perfil" referrerpolicy="no-referrer" @error="avatarFailed=true"><span v-else class="avatar-fallback">{{(state.profileName || user?.displayName || 'U').slice(0,1).toUpperCase()}}</span><div><b>{{state.profileName || user?.displayName || 'Minha conta'}}</b><small>{{user?.email}}</small></div></div><button class="account-action" @click="openSalary(); closeProfileMenu()"><UIcon name="i-lucide-settings-2" />Configurações</button><button class="account-action logout" @click="exitAccount(); closeProfileMenu()"><UIcon name="i-lucide-log-out" />Sair</button></div></details></div></header><div class="content" :key="page"><div class="heading"><div><div class="caption">SEU DINHEIRO, COM CLAREZA &nbsp; / &nbsp; {{monthLabel}}</div><h1>{{page==='monthly'?'Resumo mensal':page==='reports'?'Relatórios':page==='history'?'Histórico de lançamentos':'Configurações'}}</h1><p>{{page==='monthly'?'Organize seus compromissos e acompanhe o que fica disponível.':page==='reports'?'Entenda para onde seu dinheiro está indo.':page==='history'?'Consulte e filtre seus lançamentos.':'Cuide do seu perfil e defina seu salário.'}}</p></div><div class="month month-picker" v-if="page!=='settings'"><button @click="shift(-1)" aria-label="Mês anterior"><UIcon name="i-lucide-chevron-left" /></button><label class="month-display"><span>{{monthLabel}}</span><UIcon name="i-lucide-chevron-down" /><input type="month" v-model="month" aria-label="Selecionar mês" @click="($event.target as HTMLInputElement).showPicker?.()"></label><button @click="shift(1)" aria-label="Próximo mês"><UIcon name="i-lucide-chevron-right" /></button></div></div>
<template v-if="page==='monthly'"><div class="summary"><div class="metric"><div class="label">Salário base</div><strong>{{money(current.salary)}}</strong><button class="salary-link" @click="openSalary">Editar salário →</button></div><div class="metric"><div class="label">Total a pagar</div><strong>{{money(totalPay)}}</strong><div class="payment-breakdown"><div class="payment-cell payment-cell-paid"><span>Pago</span><b>{{money(paid)}}</b></div><div class="payment-cell payment-cell-pending"><span>Falta pagar</span><b>{{money(totalPay-paid)}}</b></div></div></div><div class="metric"><div class="label">Descontos + ganhos</div><strong class="value-extra">{{money(extra)}}</strong><div class="hint">Descontos e entradas extras</div></div><div class="metric"><div class="label">Me devem</div><strong class="value-owed">{{money(owed)}}</strong><div class="hint">{{money(received)}} recebido</div></div><div class="metric balance" :class="{negative:balance<0}"><div class="label">SALDO PREVISTO</div><strong>{{money(balance)}}</strong><div class="hint">Saldo previsto após todos os lançamentos</div></div></div><div class="progress"><div><b>Progresso do mês</b><small>Contas pagas até agora</small></div><div class="track"><div class="fill" :style="{width:progress+'%'}"></div></div><span class="percent">{{progress}}%</span></div><div class="grid"><section class="panel"><div class="panel-head section-head"><div><h2>Minhas contas</h2><p>Despesas e compromissos deste mês</p></div><button class="btn" @click="openNew('conta')">+ Adicionar</button></div><div class="columns"><span>DESCRIÇÃO</span><span>VALOR</span><span class="category">CATEGORIA</span><span>STATUS</span></div><div class="item" v-for="item in current.items" :key="item.id" :class="{done:item.paid}"><div><div class="name">{{item.name}}</div><small>{{item.due?(isIncome(item)?'Recebimento dia ':'Vence dia ')+item.due:isIncome(item)?'Entrada extra':'Conta mensal'}} <span v-if="item.discount||item.gain && !isIncome(item)"> · {{item.discount?'Desc. '+money(item.discount):''}} {{item.gain?' + '+money(item.gain):''}}</span></small><div class="edit-buttons"><button class="entry-edit" @click="edit(item,'conta')" :aria-label="'Editar '+item.name"><UIcon name="i-lucide-pencil" /><span>Editar</span></button><button class="entry-delete" @click="remove(item,'conta')" :aria-label="'Excluir '+item.name"><UIcon name="i-lucide-trash" /><span>Excluir</span></button></div></div><span class="amount">{{money(isIncome(item)?item.gain:item.pay)}}</span><span class="category"><span class="tag">{{item.category||'Outros'}}</span></span><button class="pay-button" :class="{paid:item.paid,receiving:isIncome(item)}" @click="item.paid=!item.paid" :aria-label="isIncome(item)?(item.paid?'Desmarcar recebimento':'Marcar como recebido'):(item.paid?'Desmarcar pagamento':'Marcar conta como paga')" :aria-pressed="!!item.paid">{{isIncome(item) ? (item.paid ? "✓ Recebido" : "Receber") : (item.paid ? "✓ Pago" : "Pagar")}}</button></div><div v-if="!current.items.length" class="empty">Nenhuma conta neste mês.</div><div class="foot"><span>Total das contas</span><b>{{money(totalPay)}}</b></div></section><section class="panel"><div class="panel-head section-head"><div><h2>Me devem</h2><p>Valores a receber</p></div><button class="btn" @click="openNew('receber')">+ Adicionar</button></div><div class="columns receivable"><span>DESCRIÇÃO</span><span>VALOR</span><span>OK</span></div><div class="item receivable" v-for="item in current.receivables" :key="item.id" :class="{done:item.paid}"><div><div class="name">{{item.name}}</div><small>{{item.paid?'Recebido':'A receber'}}</small><div class="edit-buttons"><button class="entry-edit" @click="edit(item,'receber')" :aria-label="'Editar '+item.name"><UIcon name="i-lucide-pencil" /><span>Editar</span></button><button class="entry-delete" @click="remove(item,'receber')" :aria-label="'Excluir '+item.name"><UIcon name="i-lucide-trash" /><span>Excluir</span></button></div></div><span class="amount">{{money(item.value)}}</span><button class="pay-button receiving" :class="{paid:item.paid}" @click="item.paid=!item.paid" :aria-label="item.paid?'Desmarcar recebimento':'Marcar como recebido'" :aria-pressed="!!item.paid">{{item.paid ? "✓ Recebido" : "Receber"}}</button></div><div v-if="!current.receivables.length" class="empty">Nenhum valor a receber.</div><div class="foot"><span>Total a receber</span><b>{{money(owed)}}</b></div></section></div><p class="note">✦ &nbsp;O saldo considera todas as contas e valores a receber, mesmo os que ainda estão pendentes.</p></template>
<template v-if="page==='settings'"><section class="panel settings-panel"><div class="panel-head"><h2>Perfil e salário</h2><p class="sub">Escolha como seu salário será aplicado aos meses.</p></div><div class="settings-content"><button class="settings-backup" @click="modal='backup'"><UIcon name="i-lucide-cloud" /><span><b>Dados e backup</b><small>Importar, exportar e gerenciar seus arquivos</small></span><UIcon name="i-lucide-chevron-right" /></button><div class="field"><label for="profile-name">Seu nome</label><input id="profile-name" v-model.trim="profileDraft" placeholder="Como podemos chamar você?"></div><div class="field"><label for="salary-setting">Salário (R$)</label><input id="salary-setting" type="number" min="0" step="0.01" v-model.number="salaryValue"></div><div class="field"><label for="salary-scope">Aplicar salário</label><select id="salary-scope" v-model="salaryScope"><option value="all">Todos os meses</option><option value="future">A partir deste mês</option><option value="one">Apenas este mês</option></select><small>Mês selecionado: {{monthLabel}}. As opções de todos os meses e a partir deste mês também valem para meses futuros.</small></div><button class="btn primary" @click="saveSalary">Salvar alterações</button><p v-if="salaryMessage" class="feedback" role="status">{{salaryMessage}}</p></div></section></template><template v-if="page==='reports'"><div class="grid"><section class="panel"><div class="panel-head"><h2>Gastos por mês</h2><span class="sub">Total de contas lançadas em cada período</span></div><div class="chart"><canvas id="monthlyChart"></canvas></div></section><section class="panel"><div class="panel-head"><h2>Gastos por categoria</h2><span class="sub">Distribuição em {{monthLabel}}</span></div><div class="chart"><canvas id="categoryChart"></canvas></div></section></div></template><template v-if="page==='history'"><div class="toolbar"><select v-model="filter" class="btn"><option value="">Todas as categorias</option><option v-for="c in categories">{{c}}</option></select><button class="btn" @click="exportCSV">Exportar CSV</button><button class="btn" @click="exportExcel">Exportar Excel</button><button class="btn" @click="printPage">Imprimir / PDF</button></div><section class="panel"><div class="item" v-for="x in history"><div><div class="name">{{x.name}}</div><small>{{x.month}} · {{x.category||'Outros'}}</small></div><span class="amount">{{money(isIncome(x)?x.gain:x.pay)}}</span><span class="tag category">{{x.paid?(isIncome(x)?'Recebido':'Pago'):'Pendente'}}</span></div><div class="empty" v-if="!history.length">Nenhum lançamento encontrado.</div></section></template></div></main></div><nav v-if="entered" class="mobile"><button v-for="n in nav.filter(item=>item.id!=='settings')" :class="{active:page===n.id}" @click="go(n.id)"><UIcon :name="`i-lucide-${n.icon}`" />{{n.short}}</button></nav>
<div class="overlay" v-if="modal" @click.self="modal=''" role="dialog" aria-modal="true"><div class="modal"><template v-if="modal==='entry'"><button class="modal-close" @click="modal=''" aria-label="Fechar janela"><UIcon name="i-lucide-x" /></button><h2>{{editing?'Editar lançamento':'Novo lançamento'}}</h2><p>Organize suas contas e parcelas em poucos passos.</p><form @submit.prevent="saveItem"><div class="form"><div class="field full"><label for="type">Tipo</label><select id="type" v-model="form.type" :disabled="!!editing"><option value="conta">{{editing && isIncome(editing)?"Entrada extra / a receber":"Despesa / conta"}}</option><option value="receber">Me devem / a receber</option></select></div><div class="field full"><label for="name">Descrição</label><input id="name" required v-model.trim="form.name" placeholder="Ex.: Internet, moto, empréstimo"></div><div class="field"><label for="value">{{editing && isIncome(editing)?"Valor a pagar (R$) — zero para entrada":"Valor da parcela (R$)"}}</label><input id="value" required type="number" min="0" step="0.01" v-model.number="form.value"></div><div class="field"><label for="start">Mês de início</label><input id="start" required type="month" v-model="form.start" :disabled="!!editing"></div><template v-if="form.type==='conta'"><div class="field"><label for="discount">Desconto (R$)</label><input id="discount" type="number" min="0" step="0.01" v-model.number="form.discount"></div><div class="field"><label for="gain">Valor a receber / entrada extra (R$)</label><input id="gain" type="number" min="0" step="0.01" v-model.number="form.gain"></div><div class="field"><label for="category">Categoria</label><select id="category" v-model="form.category"><option v-for="c in categories">{{c}}</option></select></div><div class="field"><label for="due">Dia de vencimento</label><input id="due" type="number" min="1" max="31" v-model.number="form.due" placeholder="Opcional"></div></template><template v-if="!editing"><div class="field"><label for="total">Quantidade total de parcelas</label><select id="total" v-model.number="form.total"><option v-for="n in 60" :value="n">{{n}}x</option></select></div><div class="field"><label for="initial">Parcela inicial</label><select id="initial" v-model.number="form.initial"><option v-for="n in form.total" :value="n">{{n}} de {{form.total}}</option></select></div></template><div class="field full" v-if="editing"><label for="extra-months">Acrescentar parcelas</label><select id="extra-months" v-model.number="form.extraMonths"><option :value="0">Não acrescentar</option><option v-for="n in extensionLimit" :value="n">Mais {{n}} {{n===1?'mês':'meses'}}</option></select><small class="sub">As novas parcelas começam após o último mês desta dívida, com o valor informado acima e status pendente.</small></div><div class="field full" v-if="editing && editing.groupId"><label for="scope">Aplicar alteração</label><select id="scope" v-model="form.scope"><option value="one">Somente neste mês</option><option value="future">Nesta e nas parcelas futuras</option></select></div></div><div class="actions"><button type="button" class="btn" @click="modal=''">Cancelar</button><button class="btn primary">Salvar lançamento</button></div></form></template><template v-else><h2>Dados e backup</h2><p>Seus dados ficam salvos neste navegador. Exporte um backup antes de trocar de dispositivo.</p><div class="toolbar"><button class="btn" @click="backup">Exportar JSON</button><label class="btn">Importar JSON <input type="file" accept=".json" hidden @change="importJSON"></label><label class="btn">Importar planilha <input type="file" accept=".csv,.xlsx,.xls" hidden @change="importSheet"></label></div><p>Para importar planilhas, use as colunas <b>mes, nome, pagar, desconto, ganhar, categoria</b>, com o mês no formato AAAA-MM.</p><p>{{message}}</p><h3>Sincronização com Firebase</h3><p>{{user ? 'Conectado como ' + user.email : 'Para sincronizar, volte para o login e entre com Google.'}}</p><p v-if="syncError" class="feedback" role="alert">{{syncError}}</p><p>Os dados locais e da conta são separados. Para migrar dados locais, exporte o JSON e importe após entrar.</p><p>Biometria e notificações em segundo plano ainda não estão disponíveis nesta versão.</p><div class="actions"><button class="btn" @click="modal=''">Fechar</button></div></template></div></div><Transition name="dialog"><div v-if="logoutOpen" class="overlay logout-overlay" @click.self="!logoutBusy && (logoutOpen=false)" @keydown.esc="!logoutBusy && (logoutOpen=false)"><section class="modal logout-dialog" role="alertdialog" aria-modal="true" aria-labelledby="logout-title" aria-describedby="logout-description"><div class="logout-symbol"><UIcon name="i-lucide-log-out" /></div><h2 id="logout-title">Sair da conta?</h2><p id="logout-description">Você precisará entrar com Google para acessar suas finanças novamente.</p><p v-if="dirty || saving || conflicted" class="logout-warning">Há alterações ainda não sincronizadas. Cancele e exporte um backup antes de sair.</p><div class="logout-actions"><button class="btn" autofocus :disabled="logoutBusy" @click="logoutOpen=false">Cancelar</button><button class="btn danger" :disabled="logoutBusy" @click="confirmLogout">{{logoutBusy ? 'Saindo...' : 'Sair da conta'}}</button></div></section></div></Transition><Transition name="dialog"><div v-if="confirmation" class="overlay logout-overlay" @click.self="answer(false)" @keydown.esc="answer(false)"><section class="modal logout-dialog" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><h2 id="confirm-title">{{confirmation.title}}</h2><p>{{confirmation.description}}</p><div class="logout-actions"><button class="btn" @click="answer(false)">Cancelar</button><button class="btn" :class="confirmation.danger?'danger':'primary'" @click="answer(true)">{{confirmation.label}}</button></div></section></div></Transition></UApp></template>
<script setup lang="ts">
import { Chart, registerables } from 'chart.js'
import * as XLSX from 'xlsx'
import { initializeApp, getApps } from 'firebase/app'
import { getAuth, GoogleAuthProvider, signInWithPopup, signOut as firebaseSignOut, onAuthStateChanged, setPersistence, browserLocalPersistence, browserSessionPersistence, type User } from 'firebase/auth'
import { getFirestore, doc, getDoc, onSnapshot, runTransaction, type Unsubscribe } from 'firebase/firestore'
Chart.register(...registerables)
type Item={id:string;groupId?:string;name:string;pay?:number;discount?:number;gain?:number;value?:number;paid:boolean;category?:string;due?:number|string;note?:string}
type Month={salary:number;items:Item[];receivables:Item[]}
type State={months:Record<string,Month>;profileName:string;salaryRules:Record<string,number>;defaultSalary:number}
const authReady=ref(false)
const rememberBrowser=ref(false),rememberedProfile=ref<{name:string;email:string;photoURL:string}|null>(null)
const toast=useToast()
const profileDraft=ref('')
const confirmation=ref<{title:string;description:string;danger:boolean;label:string}|null>(null)
let confirmationResolve:((value:boolean)=>void)|undefined
function ask(title:string,description:string,danger=false,label='Confirmar'){return new Promise<boolean>(resolve=>{confirmationResolve=resolve;confirmation.value={title,description,danger,label}})}
function answer(value:boolean){confirmation.value=null;confirmationResolve?.(value);confirmationResolve=undefined}
function notify(title:string){toast.add({title,icon:'i-lucide-circle-check',color:'success'})}
const avatarFailed=ref(false)
const logoutOpen=ref(false),logoutBusy=ref(false)
function closeProfileMenu(){document.querySelectorAll('details.profile-menu[open]').forEach(el=>el.removeAttribute('open'))}
const isIncome=(item:Item)=>Number(item.pay||0)===0 && Number(item.gain||0)>0
const uid=()=>crypto.randomUUID()
const base=():Item[]=>[]
const addMonth=(m:string,n:number)=>{const [y=2026,mo=1]=m.split('-').map(Number),d=new Date(y,mo-1+n,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}
function seed():State{return {months:{},profileName:'',salaryRules:{},defaultSalary:0}}
const state=reactive<State>(seed()),month=ref(new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')),page=ref('monthly'),modal=ref(''),theme=ref(false),filter=ref(''),message=ref(''),entered=ref(false),authBusy=ref(false),salaryValue=ref(0),salaryScope=ref('one'),salaryMessage=ref('')
const nav=[{id:'monthly',label:'Controle mensal',short:'Início',icon:'layout-dashboard'},{id:'reports',label:'Relatórios',short:'Relatórios',icon:'chart-no-axes-column'},{id:'history',label:'Histórico',short:'Histórico',icon:'list-filter'},{id:'settings',label:'Configurações',short:'Ajustes',icon:'settings-2'}],categories=['Cartão','Moradia','Transporte','Alimentação','Saúde','Lazer','Outros']
function salaryFor(m:string){const key=Object.keys(state.salaryRules).filter(k=>k<=m).sort().pop();return key ? state.salaryRules[key] ?? 0 : state.defaultSalary}
function ensure(m:string):Month{if(!state.months[m])state.months[m]={salary:salaryFor(m),items:base(),receivables:[]};return state.months[m]!}
function openSalary(){profileDraft.value=state.profileName||user.value?.displayName||'';salaryValue.value=current.value.salary;salaryMessage.value='';go('settings')}
async function saveSalary(){const value=Number(salaryValue.value);if(!Number.isFinite(value)||value<0){salaryMessage.value='Informe um salário válido.';return}if(!await ask('Salvar alterações?',`O salário de ${money(value)} será aplicado ${salaryScope.value==='all'?'a todos os meses':salaryScope.value==='future'?'a partir de '+monthLabel.value:'somente em '+monthLabel.value}.`))return;state.profileName=profileDraft.value.trim();if(salaryScope.value==='all'){state.defaultSalary=value;state.salaryRules={};Object.values(state.months).forEach(d=>d.salary=value)}else if(salaryScope.value==='future'){state.salaryRules[month.value]=value;for(const key of Object.keys(state.salaryRules))if(key>month.value)delete state.salaryRules[key];for(const [key,d] of Object.entries(state.months))if(key>=month.value)d.salary=value}else current.value.salary=value;salaryMessage.value='';notify('Perfil e salário atualizados');go('monthly')}
const current=computed(()=>ensure(month.value)),totalPay=computed(()=>current.value.items.reduce((a,x)=>a+(+x.pay!||0),0)),paid=computed(()=>current.value.items.reduce((a,x)=>a+(x.paid?(+x.pay!||0):0),0)),extra=computed(()=>current.value.items.reduce((a,x)=>a+(+x.discount!||0)+(+x.gain!||0),0)),owed=computed(()=>current.value.receivables.reduce((a,x)=>a+(+x.value!||0),0)),received=computed(()=>current.value.receivables.reduce((a,x)=>a+(x.paid?(+x.value!||0):0),0)),balance=computed(()=>Number(current.value.salary||0)-totalPay.value+extra.value+owed.value),progress=computed(()=>totalPay.value?Math.min(100,Math.round(paid.value/totalPay.value*100)):0),monthLabel=computed(()=>new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(month.value+'-01T12:00:00'))),history=computed(()=>Object.entries(state.months).sort((a,b)=>b[0].localeCompare(a[0])).flatMap(([m,d])=>d.items.filter(x=>!filter.value||x.category===filter.value).map(x=>({...x,month:m}))))
const money=(n:number|undefined)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n||0)
const form=reactive({type:'conta',name:'',value:0,discount:0,gain:0,start:'',total:1,initial:1,category:'Outros',due:'' as string|number,scope:'one',extraMonths:0}),editing=ref<Item|null>(null)
function openNew(type:string){editing.value=null;Object.assign(form,{extraMonths:0,type,name:'',value:0,discount:0,gain:0,start:month.value,total:1,initial:1,category:'Outros',due:'',scope:'one'});modal.value='entry'}
function edit(item:Item,type:string){editing.value=item;Object.assign(form,{extraMonths:0,type,name:item.name.replace(/ \d+\/\d+$/,''),value:type==='conta'?item.pay:item.value,discount:item.discount||0,gain:item.gain||0,start:month.value,category:item.category||'Outros',due:item.due||'',scope:'one'});modal.value='entry'}
function installmentSeries(item:Item){const key=form.type==='conta'?'items':'receivables';return Object.entries(state.months).flatMap(([m,d])=>d[key].filter(x=>x.id===item.id||!!item.groupId&&x.groupId===item.groupId).map(x=>({month:m,item:x}))).sort((a,b)=>a.month.localeCompare(b.month))}
const extensionLimit=computed(()=>{if(!editing.value)return 59;const series=installmentSeries(editing.value);const total=Math.max(1,...series.map(x=>Number(x.item.name.match(/ (\d+)\/(\d+)$/)?.[2]||1)));return Math.max(0,60-total)})
function extendInstallments(item:Item){const series=installmentSeries(item),last=series.at(-1);if(!last)return;const total=Math.max(1,...series.map(x=>Number(x.item.name.match(/ (\d+)\/(\d+)$/)?.[2]||1))),extra=Math.min(Math.max(0,Math.trunc(form.extraMonths)),60-total);if(!extra)return;const groupId=item.groupId||uid(),newTotal=total+extra;series.forEach(({item:x})=>{const part=Number(x.name.match(/ (\d+)\/(\d+)$/)?.[1]||1);x.groupId=groupId;x.name=x.name.replace(/ \d+\/\d+$/,'')+` ${part}/${newTotal}`});for(let i=1;i<=extra;i++){const target=ensure(addMonth(last.month,i));const added:Item={id:uid(),groupId,name:form.name+` ${total+i}/${newTotal}`,paid:false,category:form.category,due:form.due};if(form.type==='conta'){Object.assign(added,{pay:Number(form.value)||0,discount:Number(form.discount)||0,gain:Number(form.gain)||0});target.items.push(added)}else{added.value=Number(form.value)||0;target.receivables.push(added)}}}
async function saveItem(){if(!form.name)return;if(editing.value&&!await ask('Salvar alterações?',(form.scope==='future'?'Este lançamento e as parcelas futuras serão atualizados.':'As alterações serão aplicadas somente neste mês.')+(form.extraMonths?` Serão acrescentadas ${form.extraMonths} parcelas ao final da dívida, e a numeração total será atualizada.`:'')))return;if(editing.value){for(const [m,d] of Object.entries(state.months)){if(m===month.value||form.scope==='future'&&m>=month.value){for(const x of (form.type==='conta'?d.items:d.receivables)){if(x.id===editing.value.id||form.scope==='future'&&editing.value.groupId&&x.groupId===editing.value.groupId){const suffix=x.name.match(/ \d+\/\d+$/)?.[0]||'';Object.assign(x,{name:form.name+suffix,category:form.category,due:form.due});if(form.type==='conta')Object.assign(x,{pay:+form.value,discount:+form.discount||0,gain:+form.gain||0});else x.value=+form.value}}}}}else{const total=+form.total,initial=Math.min(+form.initial,total),groupId=total>1?uid():undefined;for(let i=initial;i<=total;i++){const d=ensure(addMonth(form.start,i-initial)),item:Item={id:uid(),groupId,name:form.name+(total>1?` ${i}/${total}`:''),paid:false,category:form.category,due:form.due};if(form.type==='conta'){Object.assign(item,{pay:+form.value,discount:+form.discount||0,gain:+form.gain||0});d.items.push(item)}else{item.value=+form.value;d.receivables.push(item)}}}if(editing.value&&form.extraMonths)extendInstallments(editing.value);modal.value='';notify(editing.value?'Lançamento atualizado':'Lançamento adicionado')}
async function remove(item:Item,type:string){if(!await ask('Excluir lançamento?',`Deseja excluir ${item.name}?`,true,'Excluir'))return;const future=!!item.groupId&&await ask('Aplicar às parcelas futuras?','Você já confirmou a exclusão deste lançamento. Deseja excluir também as parcelas futuras? Cancelar mantém a exclusão apenas deste mês.',true,'Excluir futuras');for(const [m,d] of Object.entries(state.months)){const key=type==='conta'?'items':'receivables';d[key]=d[key].filter(x=>future?!(m>=month.value&&x.groupId===item.groupId):x.id!==item.id)}notify('Lançamento excluído')}
function shift(n:number){month.value=addMonth(month.value,n)}function go(p:string){if(p==='settings'){profileDraft.value=state.profileName||user.value?.displayName||'';salaryValue.value=current.value.salary;salaryMessage.value=''}page.value=p;if(import.meta.client){window.history.replaceState(null,'','#'+p);window.scrollTo({top:0,behavior:'smooth'})};nextTick(()=>{if(p==='reports')draw()})}
let charts:Chart[]=[]
function draw(){charts.forEach(c=>c.destroy());charts=[];const keys=Object.keys(state.months).sort(),data=keys.map(k=>state.months[k]!.items.reduce((a,x)=>a+(+x.pay!||0),0));const el=document.getElementById('monthlyChart') as HTMLCanvasElement|null;if(!el)return;charts.push(new Chart(el,{type:'bar',data:{labels:keys,datasets:[{data,backgroundColor:'#b9f36b',borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{grid:{color:'#27323c'}}}}}));const el2=document.getElementById('categoryChart') as HTMLCanvasElement|null;if(!el2)return;const vals=categories.map(c=>current.value.items.filter(x=>(x.category||'Outros')===c).reduce((a,x)=>a+(+x.pay!||0),0));charts.push(new Chart(el2,{type:'doughnut',data:{labels:categories,datasets:[{data:vals,backgroundColor:['#b9f36b','#6dbda0','#7994dc','#edbf7e','#be8ddd','#ee8f91','#70828a'],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'72%',plugins:{legend:{position:'bottom',labels:{boxWidth:8,color:'#8e9ca6'}}}}}))}
function download(name:string,data:string,type:string){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function backup(){download('meu-controle-backup.json',JSON.stringify(state,null,2),'application/json')}
function importJSON(e:Event){const input=e.target as HTMLInputElement,f=input.files?.[0];if(!f)return;const r=new FileReader();r.onload=async()=>{try{const x=JSON.parse(String(r.result));if(!x.months||typeof x.months!=='object')throw Error();if(await ask('Importar backup?','Os dados atuais desta conta serão substituídos pelos dados do arquivo. Exporte um backup antes de continuar se quiser guardar a versão atual.',true,'Importar backup')){state.months=x.months;state.profileName=x.profileName||'';state.salaryRules=x.salaryRules||{};state.defaultSalary=x.defaultSalary||0;message.value='';modal.value='';notify('Backup importado');go('monthly')}}catch{message.value='Arquivo de backup inválido.'}};r.readAsText(f);input.value=''}
function exportCSV(){const rows=[['mes','nome','pagar','desconto','ganhar','categoria','pago'],...history.value.map(x=>[x.month,x.name,x.pay,x.discount,x.gain,x.category,x.paid])];download('lancamentos.csv','\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\n'),'text/csv')}
function exportExcel(){const ws=XLSX.utils.json_to_sheet(history.value.map(x=>({mes:x.month,nome:x.name,pagar:x.pay,desconto:x.discount,ganhar:x.gain,categoria:x.category,pago:x.paid}))),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Lançamentos');XLSX.writeFile(wb,'lancamentos.xlsx')}
function importSheet(e:Event){const input=e.target as HTMLInputElement,f=input.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const wb=XLSX.read(r.result,{type:'array'}),sheet=wb.Sheets[wb.SheetNames[0]!];if(!sheet)throw Error();const rows=XLSX.utils.sheet_to_json<Record<string,unknown>>(sheet),valid=rows.filter(x=>/^\d{4}-\d{2}$/.test(String(x.mes))&&x.nome);if(!valid.length)throw Error();if(confirm(`Importar ${valid.length} lançamentos?`))valid.forEach(x=>ensure(String(x.mes)).items.push({id:uid(),name:String(x.nome),pay:Number(x.pagar)||0,discount:Number(x.desconto)||0,gain:Number(x.ganhar)||0,category:String(x.categoria||'Outros'),paid:false}));message.value=`${valid.length} linhas encontradas.`}catch{message.value='Planilha inválida. Confira as colunas e o mês AAAA-MM.'}};r.readAsArrayBuffer(f);input.value=''}
function printPage(){window.print()}
function loadState(data:Partial<State>){state.months=data.months||{};state.profileName=data.profileName||'';state.salaryRules=data.salaryRules||{};state.defaultSalary=data.defaultSalary||0}
function exitAccount(){logoutOpen.value=true}
async function confirmLogout(){logoutBusy.value=true;try{await performLogout();logoutOpen.value=false}finally{logoutBusy.value=false}}
async function performLogout(){if(user.value){await signOut()}entered.value=false;applying=true;loadState(seed());await nextTick();applying=false;message.value=''}
onMounted(()=>{const requested=window.location.hash.slice(1);if(nav.some(n=>n.id===requested))go(requested);theme.value=localStorage.getItem('theme')==='light';watch(theme,v=>{document.body.classList.toggle('light',v);localStorage.setItem('theme',v?'light':'dark')},{immediate:true});watch(state,()=>{if(entered.value&&!applying)localStorage.setItem(user.value?'meu-controle-v2-'+user.value.uid:'meu-controle-v2-local',JSON.stringify(state))},{deep:true})})
const firebaseConfig={apiKey:'AIzaSyAZOOyUCF3mGe8OuwDLolYPNQXeYbqO5wY',authDomain:'sant-financas.firebaseapp.com',projectId:'sant-financas',storageBucket:'sant-financas.firebasestorage.app',messagingSenderId:'107920584711',appId:'1:107920584711:web:790b4a9e3ed244ff12baa2'}
const firebaseApp=getApps()[0]||initializeApp(firebaseConfig),auth=getAuth(firebaseApp),db=getFirestore(firebaseApp)
const user=ref<User|null>(null),cloudStatus=ref('Salvo neste dispositivo'),syncError=ref('')
let unsubscribe:Unsubscribe|undefined,syncTimer:ReturnType<typeof setTimeout>|undefined,applying=false,revision=0,dirty=false,saving=false,conflicted=false,generation=0
async function activate(u:User){avatarFailed.value=false;const gen=++generation;unsubscribe?.();user.value=u;cloudStatus.value='Carregando dados...';const refDoc=doc(db,'users',u.uid,'finance','main');try{const snap=await getDoc(refDoc);if(gen!==generation)return;applying=true;loadState(snap.exists()?snap.data().data:seed());revision=snap.exists()?Number(snap.data().revision||0):0;dirty=false;conflicted=false;syncError.value='';entered.value=true;await nextTick();applying=false;cloudStatus.value='Nuvem conectada';unsubscribe=onSnapshot(refDoc,async snap=>{if(gen!==generation||!snap.exists())return;const incoming=Number(snap.data().revision||0);if(incoming<=revision||saving)return;if(dirty){conflicted=true;cloudStatus.value='Conflito de sincronização';syncError.value='Os dados foram alterados em outro dispositivo. Exporte o backup local e entre novamente para carregar a versão da nuvem.';return}applying=true;loadState(snap.data().data);revision=incoming;await nextTick();applying=false},error=>{cloudStatus.value='Erro de sincronização';syncError.value=error.message})}catch(e){if(gen!==generation)return;user.value=null;entered.value=false;message.value='Não foi possível carregar os dados. Confira as regras do Firestore e tente novamente. '+(e instanceof Error?e.message:'')}}
async function push(){if(!user.value||saving||conflicted||!dirty)return;const gen=generation,refDoc=doc(db,'users',user.value.uid,'finance','main'),snapshot=JSON.parse(JSON.stringify(state)),expected=revision;dirty=false;saving=true;try{await runTransaction(db,async transaction=>{const remote=await transaction.get(refDoc);if(Number(remote.data()?.revision||0)!==expected)throw Error('CONFLICT');transaction.set(refDoc,{revision:expected+1,data:snapshot})});if(gen!==generation)return;revision=expected+1;cloudStatus.value=dirty?'Sincronizando...':'Nuvem conectada'}catch(e){if(gen!==generation)return;dirty=true;conflicted=e instanceof Error&&e.message==='CONFLICT';cloudStatus.value=conflicted?'Conflito de sincronização':'Erro ao sincronizar';syncError.value=conflicted?'Os dados foram alterados em outro dispositivo. Exporte o backup local e entre novamente para carregar a versão da nuvem.':'Não foi possível sincronizar. Seus dados continuam neste navegador.'}finally{saving=false;if(dirty&&!conflicted&&gen===generation)syncTimer=setTimeout(push,3000)}}
async function signIn(other=false){authBusy.value=true;message.value='';try{await setPersistence(auth,rememberBrowser.value?browserLocalPersistence:browserSessionPersistence);let account=auth.currentUser;if(other||!account||rememberedProfile.value&&account.email!==rememberedProfile.value.email){const provider=new GoogleAuthProvider();provider.setCustomParameters(other?{prompt:'select_account'}:rememberedProfile.value?{login_hint:rememberedProfile.value.email}:{});account=(await signInWithPopup(auth,provider)).user}if(rememberBrowser.value){rememberedProfile.value={name:account.displayName||'Minha conta',email:account.email||'',photoURL:account.photoURL||''};localStorage.setItem('sant-remembered-profile',JSON.stringify(rememberedProfile.value))}else{localStorage.removeItem('sant-remembered-profile');rememberedProfile.value=null}localStorage.setItem('sant-last-activity-'+account.uid,String(Date.now()));await activate(account)}catch(e){message.value='Não foi possível entrar com Google. '+(e instanceof Error?e.message:'')}finally{authBusy.value=false}}
async function signOut(forgetProfile=true){++generation;clearTimeout(syncTimer);unsubscribe?.();await firebaseSignOut(auth);if(forgetProfile){localStorage.removeItem('sant-remembered-profile');rememberedProfile.value=null;rememberBrowser.value=false}user.value=null;cloudStatus.value='Salvo neste dispositivo';message.value='Conta desconectada.'}
onMounted(()=>{try{rememberedProfile.value=JSON.parse(localStorage.getItem('sant-remembered-profile')||'null');rememberBrowser.value=!!rememberedProfile.value}catch{}onAuthStateChanged(auth,async account=>{try{if(!account&&entered.value&&!authBusy.value){++generation;unsubscribe?.();clearTimeout(syncTimer);entered.value=false;user.value=null;modal.value='';logoutOpen.value=false;applying=true;loadState(seed());await nextTick();applying=false;message.value='Sessão encerrada. Entre novamente para continuar.'}if(account&&!authBusy.value&&!entered.value){const last=Number(localStorage.getItem('sant-last-activity-'+account.uid)||0);if(!last||Date.now()-last>=INACTIVITY_MS){await signOut(false);message.value='Sua sessão expirou. Entre novamente para continuar.'}else await activate(account)}}finally{authReady.value=true}},()=>{authReady.value=true;message.value='Não foi possível verificar sua sessão. Entre novamente.'});watch(state,()=>{if(entered.value&&user.value&&!applying){dirty=true;cloudStatus.value='Sincronizando...';clearTimeout(syncTimer);syncTimer=setTimeout(push,600)}},{deep:true})})
const INACTIVITY_MS=15*60*1000
let inactivityTimer:ReturnType<typeof setInterval>|undefined,lastActivityWrite=0,expiring=false
const activityKey=()=>user.value?'sant-last-activity-'+user.value.uid:''
function recordActivity(force=false){if(!entered.value||!user.value||expiring)return;const now=Date.now();if(force||now-lastActivityWrite>5000){localStorage.setItem(activityKey(),String(now));lastActivityWrite=now}}
async function checkInactivity(){if(!entered.value||!user.value||expiring)return;const last=Number(localStorage.getItem(activityKey())||0);if(last&&Date.now()-last<INACTIVITY_MS)return;expiring=true;try{if(dirty&&!conflicted&&!saving)await Promise.race([push(),new Promise(resolve=>setTimeout(resolve,1500))]);modal.value='';logoutOpen.value=false;answer(false);closeProfileMenu();entered.value=false;await signOut(false);applying=true;loadState(seed());await nextTick();applying=false;message.value='Sua sessão foi encerrada após 15 minutos sem atividade. Entre novamente para continuar.'}finally{expiring=false}}
function onActivity(){if(!entered.value)return;const last=Number(localStorage.getItem(activityKey())||0);if(last&&Date.now()-last>=INACTIVITY_MS){void checkInactivity();return}recordActivity()}
function onVisibility(){if(document.visibilityState==='visible')void checkInactivity()}
onMounted(()=>{for(const event of ['pointerdown','keydown','scroll','touchstart'])window.addEventListener(event,onActivity,{passive:true});document.addEventListener('visibilitychange',onVisibility);inactivityTimer=setInterval(checkInactivity,10000)})
onBeforeUnmount(()=>{clearInterval(inactivityTimer);for(const event of ['pointerdown','keydown','scroll','touchstart'])window.removeEventListener(event,onActivity);document.removeEventListener('visibilitychange',onVisibility)})
watch(month,()=>nextTick(()=>{if(page.value==='reports')draw()}))
</script>
